econPatch:
;(function (G) {
  const M = {"15":1.1,"16":1.5,"17":2.1};
  const dt = G.economy.dropTable;
  for (const t of ['common', 'rare', 'boss']) {
    const d = dt[t] && dt[t].awakenMaterial;
    if (d) d.qtyAreaMult = M;
  }
})(G);

passivesPatch:
;(function (G) {
  const S = 0.85;
  G.passives.unlockByDepth = G.passives.unlockByDepth.map(function (c) { return Math.max(1, Math.round(c * S)); });
  G.passives.evoFactor = 0.45;
  G.passives.evoRamp   = 1.6;
  G.passives.UNIT.atkPct = 60;
  G.passives.UNIT.ringCloses = 300;
  G.passives.UNIT.firstSpark = 4000;
  G.passives.UNIT.hpRegen    = 0.25;
  G.passives.UNIT.healOnKill = 1.5;
})(G);
